// ======= ENHANCED ADMIN PANEL - DESKTOP ONLY WITH COLLAPSIBLE SIDEBAR =======

// Configuration
const ADMIN_PASSWORD = "jawwad123" // Change this to your desired password

// Global variables for enhanced features
let selectedTags = []
let sidebarCollapsed = false

let rememberMe = false
const sessionExpiry = null

// DOM Cache
const AdminDOM = {
  loginContainer: null,
  adminToast: null,
  adminToastMessage: null,
  categorySelect: null,
  itemsContainer: null,
  itemsCount: null,
  init() {
    this.loginContainer = document.getElementById("loginContainer")
    this.adminToast = document.getElementById("admin-toast")
    this.adminToastMessage = document.getElementById("admin-toast-message")
    this.categorySelect = document.getElementById("categorySelect")
    this.itemsContainer = document.getElementById("itemsContainer")
    this.itemsCount = document.getElementById("itemsCount")
  },
}

// State Management
let currentCategory = ""
let currentItems = []
let editIndex = -1
let isAuthenticated = false

// Password Check Function
function checkPassword() {
  const passwordInput = document.getElementById("adminPassword")
  const errorDiv = document.getElementById("loginError")
  const loginButton = document.getElementById("loginButton")
  const enteredPassword = passwordInput?.value

  // Add loading state
  if (loginButton) {
    loginButton.disabled = true
    loginButton.innerHTML = '<i class="fas fa-spinner fa-spin"></i><span>Authenticating...</span>'
  }

  // Simulate authentication delay for better UX
  setTimeout(() => {
    if (enteredPassword === ADMIN_PASSWORD) {
      isAuthenticated = true

      // Handle remember me functionality
      if (rememberMe) {
        const expiryDate = new Date()
        expiryDate.setDate(expiryDate.getDate() + 7) // 7 days
        localStorage.setItem(
          "adminAuth",
          JSON.stringify({
            authenticated: true,
            expiry: expiryDate.getTime(),
            timestamp: Date.now(),
          }),
        )
        showToast("Session saved for 7 days! 🔐", "success", 2000)
      } else {
        // Session expires when browser closes
        sessionStorage.setItem(
          "adminAuth",
          JSON.stringify({
            authenticated: true,
            timestamp: Date.now(),
          }),
        )
      }

      // Enhanced login animation
      const loginContainer = document.getElementById("loginContainer")
      if (loginContainer) {
        loginContainer.style.opacity = "0"
        loginContainer.style.transform = "scale(0.9)"
        loginContainer.style.filter = "blur(10px)"

        setTimeout(() => {
          loginContainer.style.display = "none"
        }, 500)
      }

      // Show admin layout with stagger animation
      const adminLayout = document.getElementById("adminLayout")
      if (adminLayout) {
        adminLayout.classList.remove("hidden")
        adminLayout.style.opacity = "0"
        adminLayout.style.transform = "translateY(20px)"

        setTimeout(() => {
          adminLayout.style.transition = "all 0.6s cubic-bezier(0.4, 0, 0.2, 1)"
          adminLayout.style.opacity = "1"
          adminLayout.style.transform = "translateY(0)"
        }, 100)
      }

      // Initialize enhanced features
      initializeEnhancedFeatures()

      // Show welcome message with user info
      setTimeout(() => {
        const welcomeMsg = rememberMe ? "Welcome back! Session extended for 7 days 🚀" : "Welcome to Admin Panel! 🚀"
        showToast(welcomeMsg, "success", 3000)
      }, 800)

      console.log("Admin access granted!")
      return true
    } else {
      // Enhanced error handling
      if (errorDiv) {
        errorDiv.innerHTML = `
          <i class="fas fa-exclamation-triangle"></i>
          <strong>Access Denied</strong><br>
          <small>Invalid password. Please check your credentials and try again.</small>
        `
        errorDiv.style.display = "block"
      }

      // Clear password field with animation
      if (passwordInput) {
        passwordInput.value = ""
        passwordInput.style.borderColor = "#ef4444"
        passwordInput.style.boxShadow = "0 0 0 4px rgba(239, 68, 68, 0.1)"

        setTimeout(() => {
          passwordInput.style.borderColor = ""
          passwordInput.style.boxShadow = ""
          passwordInput.focus()
        }, 2000)
      }

      // Enhanced shake animation
      const loginBox = document.querySelector(".login-box")
      if (loginBox) {
        loginBox.style.animation = "errorShake 0.6s ease-in-out"
        setTimeout(() => {
          loginBox.style.animation = ""
        }, 600)
      }

      console.log("Admin access denied!")
    }

    // Reset button state
    if (loginButton) {
      loginButton.disabled = false
      loginButton.innerHTML = '<i class="fas fa-unlock"></i><span>Access Panel</span>'
    }
  }, 1200) // Realistic authentication delay
}

function toggleRememberMe() {
  rememberMe = !rememberMe
  const checkbox = document.getElementById("rememberCheckbox")
  const sessionInfo = document.getElementById("sessionInfo")

  if (checkbox) {
    if (rememberMe) {
      checkbox.classList.add("checked")
      if (sessionInfo) {
        sessionInfo.innerHTML = '<i class="fas fa-calendar-check"></i><span>Remember for 7 days</span>'
      }
    } else {
      checkbox.classList.remove("checked")
      if (sessionInfo) {
        sessionInfo.innerHTML = '<i class="fas fa-clock"></i><span>Session expires in 24h</span>'
      }
    }
  }
}

function checkExistingAuth() {
  // Check localStorage first (remember me)
  const savedAuth = localStorage.getItem("adminAuth")
  if (savedAuth) {
    try {
      const authData = JSON.parse(savedAuth)
      if (authData.authenticated && authData.expiry > Date.now()) {
        // Valid saved session
        autoLogin("Resuming saved session... 🔄")
        return true
      } else {
        // Expired session
        localStorage.removeItem("adminAuth")
      }
    } catch (e) {
      localStorage.removeItem("adminAuth")
    }
  }

  // Check sessionStorage (current session)
  const sessionAuth = sessionStorage.getItem("adminAuth")
  if (sessionAuth) {
    try {
      const authData = JSON.parse(sessionAuth)
      if (authData.authenticated) {
        // Valid session
        autoLogin("Resuming current session... 🔄")
        return true
      }
    } catch (e) {
      sessionStorage.removeItem("adminAuth")
    }
  }

  return false
}

function autoLogin(message) {
  isAuthenticated = true

  // Hide login screen immediately
  const loginContainer = document.getElementById("loginContainer")
  if (loginContainer) {
    loginContainer.style.display = "none"
  }

  // Show admin layout
  const adminLayout = document.getElementById("adminLayout")
  if (adminLayout) {
    adminLayout.classList.remove("hidden")
  }

  // Initialize features
  initializeEnhancedFeatures()

  // Show message
  setTimeout(() => {
    showToast(message, "info", 2000)
  }, 500)
}

function clearAuthSessions() {
  localStorage.removeItem("adminAuth")
  sessionStorage.removeItem("adminAuth")
}

// Logout Function
function logout() {
  const confirmed = confirm("Are you sure you want to logout? 🤔\n\nYou will be redirected to the main website.")

  if (confirmed) {
    // Clear all authentication data
    clearAuthSessions()

    // Reset authentication
    isAuthenticated = false

    // Clear any stored data
    currentCategory = ""
    currentItems = []
    editIndex = -1
    selectedTags = []

    // Show logout message
    showToast("Logging out... See you soon! 👋", "info", 2000)

    // Redirect to main site after a short delay
    setTimeout(() => {
      window.location.href = "https://adelinjawwad.github.io/jawwad-demo/"
    }, 2000)
  }
}

// Enhanced Toast System
let toastTimeout

function showToast(message, type = "success", duration = 3000) {
  const toast = document.getElementById("admin-toast")
  const toastMessage = document.getElementById("admin-toast-message")

  if (!toast || !toastMessage) {
    console.log("Toast elements not found")
    return
  }

  if (toastTimeout) {
    clearTimeout(toastTimeout)
  }

  const icon = toast.querySelector(".icon")

  toastMessage.textContent = message
  toast.className = `toast-box show ${type}`

  if (icon) {
    const iconClass = {
      success: "fas fa-check-circle",
      error: "fas fa-exclamation-circle",
      warning: "fas fa-exclamation-triangle",
      info: "fas fa-info-circle",
    }
    icon.className = `icon ${iconClass[type] || iconClass.success}`
  }

  toast.classList.remove("hidden")
  toast.classList.add("show")
  toast.classList.remove("hide")

  toastTimeout = setTimeout(() => {
    toast.classList.remove("show")
    toast.classList.add("hide")
    setTimeout(() => {
      toast.classList.add("hidden")
    }, 500)
  }, duration)
}

// Form Management
function showRelevantFields() {
  if (!isAuthenticated) return

  const cat = document.getElementById("categorySelect")?.value
  const fieldGroups = ["sharedFields", "tutorialFields", "toolsFields", "freeFields"]

  // Hide all field groups with animation
  fieldGroups.forEach((group) => {
    const element = document.getElementById(group)
    if (element) {
      element.style.opacity = "0"
      setTimeout(() => element.classList.add("hidden"), 150)
    }
  })

  // Show relevant fields with animation
  setTimeout(() => {
    if (["costumes", "hairstyles", "weapons", "others", "free"].includes(cat)) {
      showFieldGroup("sharedFields")
    }
    if (cat === "tutorials") {
      showFieldGroup("tutorialFields")
    }
    if (cat === "tools") {
      showFieldGroup("toolsFields")
      showFieldGroup("sharedFields")
    }
    if (cat === "free") {
      showFieldGroup("freeFields")
    }
  }, 150)
}

function showFieldGroup(groupId) {
  const element = document.getElementById(groupId)
  if (element) {
    element.classList.remove("hidden")
    element.style.opacity = "0"
    setTimeout(() => (element.style.opacity = "1"), 50)
  }
}

// Data Loading
async function loadItems() {
  if (!isAuthenticated) {
    showToast("Please login first!", "error")
    return
  }

  currentCategory = document.getElementById("categorySelect")?.value
  if (!currentCategory) {
    showToast("Please select a category first!", "warning")
    return
  }

  try {
    // Add loading indicator
    const container = document.getElementById("itemsContainer")
    if (container) {
      container.innerHTML =
        '<div class="col-span-full text-center py-8"><i class="fas fa-spinner fa-spin text-2xl text-pink-500"></i><p class="mt-2">Loading items...</p></div>'
    }

    const response = await fetch(`assets/data/${currentCategory}.json?v=${Date.now()}`)
    if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`)

    currentItems = await response.json()
    displayItems()
    showToast(`Loaded ${currentItems.length} items from ${currentCategory}`, "success")
  } catch (error) {
    console.error("Failed to load items:", error)
    showToast("Failed to load items. Please try again.", "error")

    const container = document.getElementById("itemsContainer")
    if (container) {
      container.innerHTML =
        '<div class="col-span-full text-center py-8 text-red-400"><i class="fas fa-exclamation-triangle text-2xl"></i><p class="mt-2">Failed to load items</p></div>'
    }
  }
}

// Enhanced Display Functions
function displayItems() {
  const itemsContainer = document.getElementById("itemsContainer")
  const itemsCount = document.getElementById("itemsCount")

  if (!itemsContainer) return

  if (currentItems.length === 0) {
    itemsContainer.innerHTML =
      '<div class="col-span-full text-center py-8 text-gray-400"><i class="fas fa-inbox text-2xl"></i><p class="mt-2">No items found</p></div>'
    return
  }

  const fragment = document.createDocumentFragment()

  currentItems.forEach((item, index) => {
    const itemDiv = document.createElement("div")
    itemDiv.className = "item-card animate-scaleUp"
    itemDiv.style.animationDelay = `${index * 0.1}s`
    itemDiv.innerHTML = generateItemHTML(item, index)
    fragment.appendChild(itemDiv)
  })

  itemsContainer.innerHTML = ""
  itemsContainer.appendChild(fragment)

  if (itemsCount) {
    itemsCount.innerHTML = `<i class="fas fa-info-circle"></i> <span>${currentItems.length} item(s) loaded</span>`
  }
}

function generateItemHTML(item, index) {
  // Smart thumbnail with proper object-fit
  const imageHTML = item.img
    ? `<img loading="lazy" src="${item.img}" style="width: 100%; height: 200px; object-fit: cover; object-position: center; margin: 0.75rem 0; border-radius: 12px; background: #374151;" alt="${item.title}">`
    : ""

  const youtubeHTML = item.youtube
    ? `<img src="https://img.youtube.com/vi/${item.youtube}/hqdefault.jpg" class="youtube-thumb" alt="YouTube thumbnail" style="width: 100%; height: 200px; object-fit: cover; object-position: center;" />
     <br><a href="https://www.youtube.com/watch?v=${item.youtube}" target="_blank" rel="noopener noreferrer" style="color: #63b3ed; text-decoration: underline;">Watch on YouTube</a><br>`
    : ""

  const extraHTML = item.extra
    ? `<button class="btn-extra btn-base">
       <i class="fas fa-key"></i>
       Password: ${item.extra}
     </button>`
    : ""

  const downloadHTML = item.download
    ? `<a href="${item.download}" target="_blank" rel="noopener noreferrer" class="btn-download btn-base">
       <i class="fas fa-download"></i>
       Download
     </a>`
    : ""

  // Tags display
  const tagsHTML =
    item.tags && item.tags.length > 0
      ? `<div class="item-tags">
       ${item.tags.map((tag) => `<span class="item-tag">${tag}</span>`).join("")}
     </div>`
      : ""

  // Description display
  const descriptionHTML =
    item.description || item.desc
      ? `<p class="text-gray-300 text-sm mt-2 mb-2">${item.description || item.desc}</p>`
      : ""

  // Enhanced Price Display with Sale Support
  const priceHTML = generatePriceHTML(item)

  const imageWithPreviewButton = item.img
    ? `
  <div class="relative mb-4">
    <img loading="lazy" src="${item.img}" alt="${item.title}" class="asset-card-media">
    <button onclick="openModal('${item.img}')" class="absolute top-2 right-2 bg-black bg-opacity-60 text-white p-2 rounded hover:bg-opacity-80 transition" title="Preview image">
      <i class="fas fa-expand"></i>
    </button>
  </div>`
    : ""

  return `
    <div class="item-card-content">
      <strong>${item.title}</strong>
      ${tagsHTML}
      ${imageWithPreviewButton}
      ${priceHTML}
      ${descriptionHTML}
      <small>
        ${youtubeHTML}
        ${extraHTML}
      </small>
    </div>
    <div class="item-actions">
      <button onclick="editItem(${index})" class="btn-edit btn-base">
        <i class="fas fa-edit"></i>
        Edit
      </button>
      <button onclick="deleteItem(${index})" class="btn-delete btn-base">
        <i class="fas fa-trash"></i>
        Delete
      </button>
      ${downloadHTML}
    </div>
  `
}

function generatePriceHTML(item) {
  if (!item.price) return ""

  let priceHTML = '<div class="item-price-container">'

  if (item.onSale && item.discount > 0) {
    // Calculate discounted price
    const originalPrice = Number.parseFloat(item.price.replace(/[^\d.]/g, ""))
    const discountedPrice = originalPrice - (originalPrice * item.discount) / 100
    const currency = item.price.replace(/[\d.]/g, "")

    priceHTML += `
      <div class="item-price on-sale">
        <i class="fas fa-fire"></i>
        <span>${discountedPrice.toFixed(0)}${currency}</span>
        <span class="original-price">${item.price}</span>
      </div>
      <div class="sale-badge">
        <i class="fas fa-percent"></i>
        -${item.discount}% OFF
      </div>
    `
  } else {
    priceHTML += `
      <div class="item-price">
        <i class="fas fa-euro-sign"></i>
        <span>${item.price}</span>
      </div>
    `
  }

  priceHTML += "</div>"
  return priceHTML
}

// Enhanced Item Management
function addItem() {
  if (!isAuthenticated) {
    showToast("Please login first!", "error")
    return
  }

  const title = document.getElementById("newTitle")?.value.trim()

  if (!title || !currentCategory) {
    showToast("Please enter a title and select a category!", "error")
    return
  }

  const newItem = {
    title,
  }

  try {
    // Add tags
    if (selectedTags.length > 0) {
      newItem.tags = [...selectedTags]
    }

    // Add universal description
    const description = document.getElementById("newDescription")?.value.trim()
    if (description) {
      newItem.description = description
    }

    // Build item based on category
    if (["costumes", "hairstyles", "weapons", "others", "free", "tools"].includes(currentCategory)) {
      // Simplified image handling
      const imageUrl = document.getElementById("newImg")?.value.trim() || ""
      if (imageUrl) {
        newItem.img = imageUrl
      }

      Object.assign(newItem, {
        download: document.getElementById("newDownload")?.value.trim(),
        price: document.getElementById("newPrice")?.value.trim(),
        preview: document.getElementById("newPreview")?.value.trim(),
      })
    }

    if (currentCategory === "free") {
      newItem.extra = document.getElementById("newFreeDesc")?.value.trim()
    }

    if (currentCategory === "tutorials") {
      const youtube = document.getElementById("newYoutube")?.value.trim()
      if (!youtube) {
        showToast("YouTube ID is required for tutorials!", "error")
        return
      }
      newItem.youtube = youtube
      // For tutorials, use the universal description field
      if (!description) {
        newItem.desc = description
      }
    }

    if (currentCategory === "tools") {
      // For tools, require description
      if (!description) {
        showToast("Description is required for tools!", "error")
        return
      }
      newItem.desc = description

      // Add sale fields for tools
      const onSale = document.getElementById("newOnSale")?.checked || false
      const discount = document.getElementById("newDiscount")?.value.trim()

      newItem.onSale = onSale
      newItem.discount = onSale && discount ? Number.parseInt(discount) : 0
    }

    // Clean up empty fields
    Object.keys(newItem).forEach((key) => {
      if (!newItem[key] && newItem[key] !== false && newItem[key] !== 0) {
        delete newItem[key]
      }
    })

    // Add or update item
    if (editIndex > -1) {
      currentItems[editIndex] = newItem
      displayItems()
      editIndex = -1
      showToast("Item updated successfully! 🎉", "success")
    } else {
      currentItems.push(newItem)
      displayItems()
      showToast("Item added successfully! ✨", "success")
    }

    clearInputs()
  } catch (error) {
    console.error("Error adding item:", error)
    showToast("Error saving item. Please check your input.", "error")
  }
}

function editItem(index) {
  if (!isAuthenticated) {
    showToast("Please login first!", "error")
    return
  }

  const item = currentItems[index]
  if (!item) {
    showToast("Item not found!", "error")
    return
  }

  // Load tags
  selectedTags = item.tags ? [...item.tags] : []
  updateSelectedTagsDisplay()
  updateTagsInput()

  // Update tag buttons
  document.querySelectorAll(".tag-btn").forEach((btn) => {
    const tagName = btn.getAttribute("data-tag")
    if (selectedTags.includes(tagName)) {
      btn.classList.add("active")
    } else {
      btn.classList.remove("active")
    }
  })

  // Load universal description
  const descriptionField = document.getElementById("newDescription")
  if (descriptionField) {
    // Citește atât desc cât și description pentru compatibilitate
    descriptionField.value = item.description || item.desc || ""
  }

  // Load image
  const imgField = document.getElementById("newImg")
  if (imgField) {
    imgField.value = item.img || ""
    // Trigger preview
    if (item.img) {
      showImagePreview(item.img)
    }
  }

  // Populate form fields
  const fieldMappings = {
    newTitle: item.title,
    newYoutube: item.youtube,
    newPrice: item.price,
    newPreview: item.preview,
    newFreeDesc: item.extra,
    newDownload: item.download,
    newDiscount: item.discount,
  }

  Object.entries(fieldMappings).forEach(([fieldId, value]) => {
    const field = document.getElementById(fieldId)
    if (field) {
      field.value = value || ""
      // Add visual feedback
      if (value) {
        field.style.borderColor = "#10b981"
        setTimeout(() => (field.style.borderColor = ""), 1000)
      }
    }
  })

  // Handle checkbox for onSale
  const onSaleField = document.getElementById("newOnSale")
  if (onSaleField) {
    onSaleField.checked = item.onSale || false
  }

  editIndex = index

  // ADDED: Switch to Add Item section when editing
  showSection("add-item")

  // Scroll to form
  document.querySelector("#newTitle").scrollIntoView({
    behavior: "smooth",
    block: "center",
  })

  showToast("Item loaded for editing 📝", "info", 2000)
}

function deleteItem(index) {
  if (!isAuthenticated) {
    showToast("Please login first!", "error")
    return
  }

  const item = currentItems[index]

  if (!item) {
    showToast("Item not found!", "error")
    return
  }

  const confirmed = confirm(`Are you sure you want to delete "${item.title}"?\n\nThis action cannot be undone.`)

  if (confirmed) {
    currentItems.splice(index, 1)
    displayItems()
    showToast("Item deleted successfully! 🗑️", "success")
  }
}

function clearInputs() {
  const allFields = [
    "newTitle",
    "newImg",
    "newYoutube",
    "newDescription",
    "newPrice",
    "newFreeDesc",
    "newDownload",
    "newPreview",
    "newDiscount",
  ]

  allFields.forEach((fieldId) => {
    const field = document.getElementById(fieldId)
    if (field) {
      field.value = ""
      field.style.borderColor = ""
    }
  })

  // Clear checkbox
  const onSaleField = document.getElementById("newOnSale")
  if (onSaleField) {
    onSaleField.checked = false
  }

  // Clear tags
  selectedTags = []
  updateSelectedTagsDisplay()
  updateTagsInput()
  document.querySelectorAll(".tag-btn").forEach((btn) => btn.classList.remove("active"))

  // Clear image previews
  const imagePreview = document.getElementById("imagePreview")
  if (imagePreview) imagePreview.classList.add("hidden")

  editIndex = -1
  showToast("Form cleared 🧹", "info", 1500)
}

// Data Export
function saveData() {
  if (!isAuthenticated) {
    showToast("Please login first!", "error")
    return
  }

  if (!currentCategory) {
    showToast("Please select and load a category first!", "warning")
    return
  }

  try {
    const jsonStr = JSON.stringify(currentItems, null, 2)
    const blob = new Blob([jsonStr], {
      type: "application/json",
    })
    const url = URL.createObjectURL(blob)

    const a = document.createElement("a")
    a.href = url
    a.download = `${currentCategory}.json`
    a.click()

    // Clean up
    setTimeout(() => URL.revokeObjectURL(url), 100)

    showToast(`File ${currentCategory}.json downloaded successfully! 📥`, "success")
  } catch (error) {
    console.error("Error saving data:", error)
    showToast("Error saving data. Please try again.", "error")
  }
}

// ======= COLLAPSIBLE SIDEBAR FUNCTIONS =======
function toggleSidebar() {
  const sidebar = document.getElementById("adminSidebar")
  const main = document.getElementById("adminMain")
  const header = document.getElementById("sidebarHeader")
  const toggleIcon = document.getElementById("toggleIcon")

  sidebarCollapsed = !sidebarCollapsed

  if (sidebarCollapsed) {
    sidebar.classList.add("collapsed")
    main.classList.add("expanded")
    header.classList.add("collapsed")
    toggleIcon.className = "fas fa-chevron-right"
  } else {
    sidebar.classList.remove("collapsed")
    main.classList.remove("expanded")
    header.classList.remove("collapsed")
    toggleIcon.className = "fas fa-chevron-left"
  }
}

// ======= SIDEBAR NAVIGATION =======
function showSection(sectionName) {
  // Hide all sections
  document.querySelectorAll(".content-section").forEach((section) => {
    section.classList.remove("active")
  })

  // Remove active class from all nav items
  document.querySelectorAll(".nav-item").forEach((item) => {
    item.classList.remove("active")
  })

  // Show selected section
  const targetSection = document.getElementById(`${sectionName}-section`)
  if (targetSection) {
    targetSection.classList.add("active")
  }

  // Add active class to clicked nav item
  const navItem = document.querySelector(`[data-section="${sectionName}"]`)
  if (navItem) {
    navItem.classList.add("active")
  }

  // Update dashboard stats when switching sections
  updateDashboardStats()
}

function toggleMobileSidebar() {
  const sidebar = document.getElementById("adminSidebar")
  if (sidebar) {
    sidebar.classList.toggle("mobile-open")
  }
}

function updateDashboardStats() {
  // Update total items
  const totalItemsEl = document.getElementById("totalItems")
  if (totalItemsEl) {
    totalItemsEl.textContent = currentItems.length
  }

  // Update current category
  const currentCategoryEl = document.getElementById("currentCategory")
  if (currentCategoryEl) {
    currentCategoryEl.textContent = currentCategory || "None"
  }
}

function setupKeyboardShortcuts() {
  document.addEventListener("keydown", (e) => {
    if (!isAuthenticated) return

    // Ctrl+S to save
    if (e.ctrlKey && e.key === "s") {
      e.preventDefault()
      saveData()
    }

    // Ctrl+N to clear form
    if (e.ctrlKey && e.key === "n") {
      e.preventDefault()
      clearInputs()
    }

    // Escape to clear form
    if (e.key === "Escape") {
      clearInputs()
    }
  })

  // Enter key on password field
  document.addEventListener("keydown", (e) => {
    if (e.key === "Enter" && document.getElementById("adminPassword") === document.activeElement) {
      checkPassword()
    }
  })
}

function setupAutoSave() {
  setInterval(() => {
    if (isAuthenticated && currentCategory && currentItems.length > 0) {
      localStorage.setItem(`admin_backup_${currentCategory}`, JSON.stringify(currentItems))
    }
  }, 30000) // Every 30 seconds
}

// Initialization
function initializeAdmin() {
  AdminDOM.init()

  // Check for existing authentication first
  if (checkExistingAuth()) {
    return // User is already authenticated
  }

  // Setup keyboard shortcuts
  setupKeyboardShortcuts()

  // Setup auto-save
  setupAutoSave()

  // Add session timeout check
  setupSessionTimeout()

  console.log("Admin panel initialized!")
}

// Add this new function for session timeout:
function setupSessionTimeout() {
  // Check session validity every 5 minutes
  setInterval(() => {
    if (isAuthenticated) {
      const savedAuth = localStorage.getItem("adminAuth")
      const sessionAuth = sessionStorage.getItem("adminAuth")

      if (savedAuth) {
        try {
          const authData = JSON.parse(savedAuth)
          if (authData.expiry <= Date.now()) {
            // Session expired
            showToast("Session expired. Please login again.", "warning", 3000)
            setTimeout(() => {
              clearAuthSessions()
              location.reload()
            }, 3000)
          }
        } catch (e) {
          // Invalid data
          clearAuthSessions()
          location.reload()
        }
      }
    }
  }, 300000) // 5 minutes
}

